const POSTS_PER_PAGE = 10

// 성능 최적화를 위한 단일 PostItem 컴포넌트
const PostItem = React.memo(({ post, index }) => {
  const { title, date, tags, thumbnail } = post.frontmatter
  const { excerpt } = post
  const { slug, readingTime } = post.fields
  
  // 1순위: frontmatter의 thumbnail 사용 (File 객체의 publicURL)
  // 2순위: HTML에서 첫 번째 이미지 추출 (gif 우선순위)
  const firstImage = useMemo(() => {
    return thumbnail?.publicURL || extractFirstImage(post.html)
  }, [thumbnail?.publicURL, post.html])
  
  // 읽기 시간 계산 (기존 포스트 페이지와 동일한 방식)
  const readingTimeText = useMemo(() => {
    return readingTime ? `${Math.round(readingTime.minutes)}분 읽기` : '1분 읽기'
  }, [readingTime])

  // 상대 시간 계산 메모이제이션
  const relativeTime = useMemo(() => {
    return getRelativeTime(date)
  }, [date])

  const handleImageError = useCallback((e) => {
    // 이미지 로딩 실패시 부모 wrapper 숨김
    const wrapper = e.target.closest('[data-image-wrapper]')
    if (wrapper) {
      wrapper.style.display = 'none'
    }
    
    // 디버깅 정보 출력 (개발 환경에서만)
    if (process.env.NODE_ENV === 'development') {
      console.warn('📸 이미지 로딩 실패:', {
        src: firstImage,
        title: title,
        naturalSrc: e.target.src,
        error: e.target.error || 'Unknown error'
      })
    }
  }, [firstImage, title])

  const handleImageLoad = useCallback((e) => {
    // 이미지 로딩 성공시 디버깅 정보 (개발 환경에서만)
    if (process.env.NODE_ENV === 'development') {
      console.log('✅ 이미지 로딩 성공:', {
        src: firstImage,
        title: title,
        naturalWidth: e.target.naturalWidth,
        naturalHeight: e.target.naturalHeight
      })
    }
  }, [firstImage, title])

  return (
    <PostWrapper>
      <PostLink to={slug}>
        <PostContent>
          <PostMainContent>
            <PostTextContent hasImage={!!firstImage}>
              <div>
                <PostHeader>
                  <PostMeta>
                    <RelativeDate>{relativeTime}</RelativeDate>
                    <ReadingTime>{readingTimeText}</ReadingTime>
                  </PostMeta>
                  <PostTitle>{title}</PostTitle>
                </PostHeader>
                <Excerpt hasImage={!!firstImage}>
                  {excerpt}
                </Excerpt>
              </div>
              {!firstImage && (
                <PostFooter>
                  <TagList tagList={tags} />
                </PostFooter>
              )}
            </PostTextContent>
          </PostMainContent>
          
          {firstImage && (
            <PostImageWrapper data-image-wrapper>
              <PostImage 
                src={firstImage} 
                alt={title} 
                loading="lazy" 
                onError={handleImageError}
                onLoad={handleImageLoad}
              />
            </PostImageWrapper>
          )}
        </PostContent>
        
        {firstImage && (
          <PostFullWidthFooter>
            <TagList tagList={tags} />
          </PostFullWidthFooter>
        )}
      </PostLink>
    </PostWrapper>
  )
})

// React.memo로 최적화된 PostList 컴포넌트
const PostList = React.memo(({ postList }) => {
  const [currentPage, setCurrentPage] = useState(1)
  
  // 페이지네이션 관련 계산 메모이제이션
  const pagination = useMemo(() => {
    const totalPages = Math.ceil(postList.length / POSTS_PER_PAGE)
    const startIndex = (currentPage - 1) * POSTS_PER_PAGE
    const endIndex = startIndex + POSTS_PER_PAGE
    const currentPosts = postList.slice(startIndex, endIndex)
    
    return { totalPages, startIndex, endIndex, currentPosts }
  }, [postList, currentPage])

  const { totalPages, startIndex, endIndex, currentPosts } = pagination

  const handlePageChange = useCallback((page) => {
    setCurrentPage(page)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }, [])

  const handlePrevPage = useCallback(() => {
    if (currentPage > 1) {
      handlePageChange(currentPage - 1)
    }
  }, [currentPage, handlePageChange])

  const handleNextPage = useCallback(() => {
    if (currentPage < totalPages) {
      handlePageChange(currentPage + 1)
    }
  }, [currentPage, totalPages, handlePageChange])

  // 페이지 번호 배열 생성 (최대 5개 페이지 표시) 메모이제이션
  const pageNumbers = useMemo(() => {
    const pages = []
    const maxVisiblePages = 5
    
    if (totalPages <= maxVisiblePages) {
      for (let i = 1; i <= totalPages; i++) {
        pages.push(i)
      }
    } else {
      if (currentPage <= 3) {
        for (let i = 1; i <= 5; i++) {
          pages.push(i)
        }
      } else if (currentPage >= totalPages - 2) {
        for (let i = totalPages - 4; i <= totalPages; i++) {
          pages.push(i)
        }
      } else {
        for (let i = currentPage - 2; i <= currentPage + 2; i++) {
          pages.push(i)
        }
      }
    }
    
    return pages
  }, [currentPage, totalPages])

  useEffect(() => {
    setCurrentPage(1)
  }, [postList])

  // 포스트가 없을 때 빈 상태 표시
  if (postList.length === 0) {
    return (
      <EmptyState>
        <div className="icon">🔍</div>
        <h3>포스트를 찾을 수 없습니다</h3>
        <p>선택하신 태그에 해당하는 포스트가 없습니다.<br />다른 태그를 선택해보세요.</p>
      </EmptyState>
    )
  }

  return (
    <>
      {postList.length > 0 && (
        <PostCount>
          총 <strong>{postList.length}</strong>개의 포스트
          {totalPages > 1 && (
            <span> (페이지 <strong>{currentPage}</strong>/{totalPages})</span>
          )}
        </PostCount>
      )}
      
      <PostListWrapper>
        {currentPosts.map((post, index) => (
          <PostItem key={post.fields.slug} post={post} index={index} />
        ))}
      </PostListWrapper>
      
      {totalPages > 1 && (
        <PaginationWrapper>
          <PaginationButton 
            onClick={handlePrevPage}
            disabled={currentPage === 1}
          >
            <FaChevronLeft />
          </PaginationButton>
          
          {pageNumbers.map(page => (
            <PaginationButton
              key={page}
              active={page === currentPage}
              onClick={() => handlePageChange(page)}
            >
              {page}
            </PaginationButton>
          ))}
          
          <PaginationButton 
            onClick={handleNextPage}
            disabled={currentPage === totalPages}
          >
            <FaChevronRight />
          </PaginationButton>
          
          <PageInfo>
            {currentPage} / {totalPages} 페이지
          </PageInfo>
        </PaginationWrapper>
      )}
    </>
  )
})

export default PostList
